p plugin file: %s'=>'Не удалось распаковать файл плагина: %s','Failed to unzip plugin file'=>'Не удалось распаковать файл плагина','Failed to activate plugin: %s'=>'Не удалось активировать плагин: %s','Failed to delete plugin: %s'=>'Не удалось удалить плагин: %s','No update available for this plugin'=>'Нет доступных обновлений для этого плагина','Invalid update information for this plugin'=>'Недействительная информация об обновлении для этого плагина','Failed to update plugin: %s'=>'Не удалось обновить плагин: %s','Plugin update failed'=>'Обновление плагина не удалось','Failed to get plugin information: %s'=>'Не удалось получить информацию о плагине: %s','ERR'=>'ERR','.'=>'.']];